var n=`0359-tiroler-grostl`;var i=`world-0359`;var o=`AT`;var a=`western-europe`;var r=4;var s=43;var d={en:`Tiroler Gröstl`,ua:`Тірольський грьостль`};var l={en:`A traditional Austria dish made with potato, smoked ham, yellow onion, chicken egg. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: картопля, копчена шинка, жовта цибуля, куряче яйце. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`potato`,600,`g`]]},{en:`Fry the ham and onions in butter, then add the boiled sliced potatoes and let their edges turn golden and crisp.`,ua:`Обсмажте шинку й цибулю на маслі, додайте скибочки вареної картоплі та підрум’яньте їх до хрустких країв.`,t:[`pan-frying`],m:11,i:[[`smoked-ham`,240,`g`],[`yellow-onion`,170,`g`],[`unsalted-butter`,65,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`dried-marjoram`,4,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 10 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 10 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:10,i:[[`chicken-egg`,4,`pcs`]]}];var g={slug:n,id:i,country:`AT`,region:a,servings:4,minutes:43,title:d,text:l,steps:u};export{o as country,g as default,i as id,s as minutes,a as region,r as servings,n as slug,u as steps,l as text,d as title};